?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?=e($imovel['nome'])?> · Central Imóveis</title><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>:root{--ink:#17212b;--muted:#697786;--line:#e1e5e9;--surface:#fff;--page:#f4f5f6;--accent:#d71920}*{box-sizing:border-box}body{margin:0;background:var(--page);color:var(--ink);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{width:min(1120px,calc(100% - 28px));margin:auto;padding:28px 0 55px}.top{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:18px}.eyebrow{font-size:10px;font-weight:900;letter-spacing:.15em;color:#818b94}.title{margin:7px 0 5px;font-size:clamp(30px,5vw,50px);line-height:1;letter-spacing:-.055em}.sub{margin:0;color:var(--muted);font-size:13px}.actions{display:flex;gap:7px;flex-wrap:wrap}.btn{border:1px solid var(--ink);border-radius:10px;padding:10px 14px;background:var(--ink);color:#fff;font-weight:800;cursor:pointer;text-decoration:none}.btn.light{background:#fff;color:var(--ink);border-color:var(--line)}.hero{background:#111;border-radius:22px;overflow:hidden;box-shadow:0 18px 55px rgba(16,24,40,.15)}.photo-stage{height:min(70vh,700px);min-height:330px;display:flex;align-items:center;justify-content:center}.photo-stage img{width:100%;height:100%;object-fit:contain}.thumbs{display:flex;gap:7px;overflow:auto;padding:10px;background:#111}.thumb{flex:0 0 66px;width:66px;height:50px;padding:0;border:2px solid transparent;border-radius:7px;overflow:hidden;background:#222;cursor:pointer}.thumb.active{border-color:#fff}.thumb img{width:100%;height:100%;object-fit:cover}.counter{padding:10px 12px;background:#111;color:#aaa;font-size:11px}.content{margin-top:18px;background:#fff;border:1px solid var(--line);border-radius:19px;padding:25px}.content h2{margin:0 0 12px;font-size:22px;letter-spacing:-.03em}.description{white-space:pre-line;color:#536170;line-height:1.75;font-size:14px;margin:0}.chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:18px}.chip{border:1px solid var(--line);border-radius:999px;padding:7px 10px;background:#fafafa;font-size:11px;font-weight:800;color:#536170}.map{height:350px;margin-top:18px;border-radius:16px;overflow:hidden;border:1px solid var(--line)}.map-note{font-size:11px;color:#89939c;margin-top:8px}.profile{display:flex;align-items:center;gap:12px;margin-top:25px;padding-top:20px;border-top:1px solid var(--line)}.profile img,.avatar{width:48px;height:48px;border-radius:50%;object-fit:cover}.avatar{display:grid;place-items:center;background:#17212b;color:#fff;font-weight:900}.profile strong{display:block;font-size:14px}.profile span{display:block;color:var(--muted);font-size:11px;margin-top:3px}.pdf-mode .hero,.pdf-mode .actions,.pdf-mode .map,.pdf-mode .thumbs,.pdf-mode .map-note{display:none}.pdf-sheet{display:none}.pdf-mode .pdf-sheet{display:block}.pdf-sheet h1{font-size:28px;margin:0 0 7px}.pdf-sheet p{color:#536170;line-height:1.6}.pdf-images img{width:100%;max-height:255mm;object-fit:contain;display:block;margin:0 auto 12px;break-inside:avoid}.pdf-footer{margin-top:18px;padding-top:12px;border-top:1px solid #ddd;font-size:10px;color:#697786}@media(max-width:700px){.top{display:block}.actions{margin-top:14px}.photo-stage{height:58vh}.content{padding:20px}.map{height:290px}}@media print{body{background:#fff}.wrap{width:100%;padding:0}.pdf-sheet{display:block!important}.content{border:0;padding:0}.profile{break-inside:avoid}}</style></head><body class="<?=isset($_GET['pdf'])?'pdf-mode':''?>"><main class="wrap">
<header class="top"><div><div class="eyebrow">CENTRAL IMÓVEIS · ANÚNCIO</div><h1 class="title"><?=e($imovel['nome'])?></h1><p class="sub"><?=e($imovel['codigo'])?><?php if(!empty($imovel['bairro'])):?> · <?=e($imovel['bairro'])?><?php endif;?></p></div><div class="actions"><button class="btn" type="button" onclick="generatePdf()" title="Baixar a galeria completa em PDF">Baixar PDF</button><button class="btn light" type="button" onclick="shareGallery()" title="Compartilhar o anúncio">Compartilhar</button></div></header>
