<section class="content"><h2>Sobre o imóvel</h2><p class="description"><?=e($imovel['descricao']??'')?:'Entre em contato para receber mais informações sobre este imóvel.'?></p><?php if($features):?><div class="chips"><?php foreach($features as $f):?><span class="chip"><?=e($f)?></span><?php endforeach;?></div><?php endif;?><?php if($hasMap):?><div id="map" class="map"></div><div class="map-note">Localização aproximada para preservar a privacidade do imóvel.</div><?php endif;?><?php if(!empty($profile['nome'])):?><div class="profile"><?php if(!empty($profile['foto_url'])):?><img src="<?=e($profile['foto_url'])?>" alt="<?=e($profile['nome'])?>"><?php else:?><div class="avatar"><?=e(mb_strtoupper(mb_substr((string)$profile['nome'],0,1)))?></div><?php endif;?><div><strong><?=e($profile['nome'])?></strong><?php if(!empty($profile['creci'])):?><span>CRECI <?=e($profile['creci'])?></span><?php endif;?></div></div><?php endif;?></section>
