</main><script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script><?php if($hasMap):?><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><?php endif;?><script>const photos=<?=json_encode(array_column($fotos,'url'),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?>;let current=0;const img=document.getElementById('mainImage'),counter=document.getElementById('counter'),thumbs=[...document.querySelectorAll('.thumb')];function selectPhoto(i){if(!photos.length)return;current=(i+photos.length)%photos.length;img.src=photos[current];counter.textContent=(current+1)+' / '+photos.length;thumbs.forEach((x,n)=>x.classList.toggle('active',n===current))}document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')selectPhoto(current+1);if(e.key==='ArrowLeft')selectPhoto(current-1)});async function shareGallery(){const data={title:<?=json_encode((string)$imovel['nome'],JSON_UNESCAPED_UNICODE)?>,text:'<?=e($imovel['nome'])?> · Central Imóveis',url:<?=json_encode($galleryUrl,JSON_UNESCAPED_SLASHES)?>};if(navigator.share){try{await navigator.share(data);return}catch(e){}}try{await navigator.clipboard.writeText(data.url);alert('Link do anúncio copiado.')}catch(e){prompt('Copie o link:',data.url)}}async function blobToData(url){const r=await fetch(url,{mode:'cors'});if(!r.ok)throw new Error('Não foi possível carregar uma foto.');const b=await r.blob();return await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=rej;fr.readAsDataURL(b)})}async function generatePdf(){if(!photos.length){alert('Este imóvel não possui fotos.');return}const button=document.querySelector('.actions .btn');const old=button.textContent;button.disabled=true;button.textContent='Preparando PDF…';try{const {jsPDF}=window.jspdf;const pdf=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});pdf.setFontSize(20);pdf.text(<?=json_encode((string)$imovel['nome'],JSON_UNESCAPED_UNICODE)?>,15,18);pdf.setFontSize(9);pdf.setTextColor(100);pdf.text('Galeria de fotos · Central Imóveis',15,25);let first=true;for(let i=0;i<photos.length;i++){const data=await blobToData(photos[i]);const props=pdf.getImageProperties(data);const maxW=180,maxH=250;const ratio=Math.min(maxW/props.width,maxH/props.height);const w=props.width*ratio,h=props.height*ratio;if(!first)pdf.addPage();first=false;pdf.addImage(data,props.fileType||'JPEG',(210-w)/2,30,w,h);pdf.setFontSize(8);pdf.setTextColor(120);pdf.text((i+1)+' / '+photos.length,15,290)}pdf.save(<?=json_encode((string)$imovel['nome'],JSON_UNESCAPED_UNICODE)?>+'.PDF')}catch(e){alert('Não foi possível gerar o PDF nesta conexão. Tente novamente.')}finally{button.disabled=false;button.textContent=old}}
<?php if($hasMap):?>const map=L.map('map',{zoomControl:false,scrollWheelZoom:false}).setView([<?=json_encode($lat)?>,<?=json_encode($lng)?>],15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap'}).addTo(map);L.circle([<?=json_encode($lat)?>,<?=json_encode($lng)?>],{radius:150,color:'#4b91b4',weight:2,fillColor:'#4b91b4',fillOpacity:.22,interactive:false}).addTo(map);L.control.zoom({position:'bottomright'}).addTo(map);<?php endif;?></script></body></html>